-- ==============================================================================
-- CLENRO - City Local Environment and Natural Resources Office
-- Cagayan de Oro City, Misamis Oriental, Philippines
-- Historical Garbage Pile-Up Reports for Decision Making Database Dump
-- Coverage: Barangay 1 to Barangay 40, Cogon Market, and Carmen Market
-- Compatible with MySQL 5.7+ / MySQL 8.0+ / MariaDB 10.4+ / phpMyAdmin
-- ==============================================================================

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `clenro_pileup_reports`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `clenro_pileup_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `incident_code` varchar(50) NOT NULL UNIQUE,
  `location_zone` varchar(100) NOT NULL,
  `barangay_number` tinyint(3) unsigned DEFAULT NULL,
  `specific_landmark` varchar(255) NOT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `incident_date` datetime NOT NULL,
  `cleared_date` datetime DEFAULT NULL,
  `turnaround_hours` decimal(6,2) DEFAULT NULL,
  `sla_status` enum('within_sla','breached_24h','breached_48h','critical_unresolved') NOT NULL DEFAULT 'within_sla',
  `waste_volume_m3` decimal(8,2) NOT NULL,
  `estimated_tonnage` decimal(8,2) NOT NULL,
  `severity` enum('low','moderate','high','critical') NOT NULL DEFAULT 'moderate',
  `waste_category` enum('market_organic_vegetable','commercial_retail_packaging','household_unsegregated','single_use_plastics','wet_fish_meat_waste','drainage_canal_debris') NOT NULL DEFAULT 'household_unsegregated',
  `root_cause` enum('market_closing_overflow','delayed_contractor_dispatch','unauthorized_vendor_dumping','monsoon_drainage_blockage','street_sweeping_backlog','collection_truck_breakdown') NOT NULL DEFAULT 'delayed_contractor_dispatch',
  `contractor_assigned` varchar(150) NOT NULL DEFAULT 'IPM CDO Urban Haulers',
  `truck_plate` varchar(50) DEFAULT NULL,
  `status` enum('resolved','in_progress','pending','chronic_hotspot') NOT NULL DEFAULT 'resolved',
  `clenro_action_taken` text DEFAULT NULL,
  `decision_recommendation` text DEFAULT NULL,
  `reported_by` varchar(100) NOT NULL DEFAULT 'CLENRO Field Inspector',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_location_zone` (`location_zone`),
  KEY `idx_barangay_number` (`barangay_number`),
  KEY `idx_incident_date` (`incident_date`),
  KEY `idx_severity` (`severity`),
  KEY `idx_status` (`status`),
  KEY `idx_root_cause` (`root_cause`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

